-- ❌ DELETE FROM events WHERE created_at < now() - interval '90 days';
--    수천만 행 → 긴 트랜잭션 · 로그 폭증 · 락 · 디스크는 안 줄어듦(공간 재사용만)

-- ✅ 배치로 나눠서
DELETE FROM events WHERE id IN (
  SELECT id FROM events WHERE created_at < $1 LIMIT 10000
);
-- 반복 + 사이에 쉬기

-- ✅✅ 더 나은 방법: 애초에 파티션으로 나눠 두고 통째로 떼어낸다
ALTER TABLE events DETACH PARTITION events_2026_05;   -- 즉시, 락 없음
DROP TABLE events_2026_05;
